import meta from "../../assets/data/quran-meta.json";

/**
 * Verified Quran metadata, generated by scripts/fetch-meta.mjs from AlQuran Cloud
 * (api.alquran.cloud/v1/meta). Nothing here is hand-typed.
 */
export interface SurahMeta {
  n: number;
  /** Arabic name as published (e.g. "سُورَةُ الكَهۡفِ"). */
  ar: string;
  en: string;
  meaning: string;
  ayahs: number;
  type: "Meccan" | "Medinan";
  /** Global number of the surah's first ayah (1..6236). */
  first: number;
}

export interface JuzMeta {
  n: number;
  surah: number;
  ayah: number;
}

export const SURAHS = meta.surahs as SurahMeta[];
export const JUZS = meta.juzs as JuzMeta[];
export const TOTAL_AYAHS = meta.totalAyahs;

export function surah(n: number): SurahMeta {
  return SURAHS[Math.min(114, Math.max(1, n)) - 1];
}

/** The Arabic name without the "سورة" prefix, for compact lists. */
export function shortArabicName(s: SurahMeta): string {
  return s.ar.replace(/^سُورَةُ\s+/, "");
}

export function globalAyah(surahNumber: number, ayah: number): number {
  return surah(surahNumber).first + ayah - 1;
}

/** Surah and ayah where a juz begins, with the surah it starts in. */
export function juzStart(n: number): { juz: JuzMeta; surah: SurahMeta } {
  const juz = JUZS[n - 1];
  return { juz, surah: surah(juz.surah) };
}

/**
 * Reciters and where their audio comes from:
 *  - `ayah`: AlQuran Cloud audio edition with one verified file per ayah (Ayah by Ayah mode;
 *    the list nur-app ships after checking each one);
 *  - `qdc`: Quran.com reciter with full-surah recordings and verified per-ayah timestamps
 *    (Full Surah mode; ids from api.quran.com/api/qdc/audio/reciters, Murattal style).
 * A reciter with only one source always plays in that mode.
 */
export interface Reciter { id: string; name: string; short: string; ayah?: string; qdc?: number }
export const RECITERS: Reciter[] = [
  { id: "ar.alafasy", name: "Mishary Rashid Alafasy", short: "Mishary Alafasy", ayah: "ar.alafasy", qdc: 7 },
  { id: "qdc.97", name: "Yasser Al-Dosari", short: "Yasser Al-Dosari", qdc: 97 },
  { id: "ar.abdulbasitmurattal", name: "Abdul Basit Abdus Samad", short: "Abdul Basit", ayah: "ar.abdulbasitmurattal", qdc: 2 },
  { id: "ar.abdurrahmaansudais", name: "Abdurrahman As-Sudais", short: "As-Sudais", ayah: "ar.abdurrahmaansudais", qdc: 3 },
  { id: "ar.mahermuaiqly", name: "Maher Al-Muaiqly", short: "Maher Al-Muaiqly", ayah: "ar.mahermuaiqly" },
  { id: "ar.husary", name: "Mahmoud Khalil Al-Husary", short: "Al-Husary", ayah: "ar.husary", qdc: 6 },
  { id: "ar.minshawi", name: "Mohamed Siddiq Al-Minshawi", short: "Al-Minshawi", ayah: "ar.minshawi", qdc: 9 },
  { id: "ar.hudhaify", name: "Ali Al-Hudhaify", short: "Al-Hudhaify", ayah: "ar.hudhaify" },
  { id: "ar.shaatree", name: "Abu Bakr Al-Shatri", short: "Abu Bakr Al-Shatri", ayah: "ar.shaatree", qdc: 4 },
];

/** The audio mode a reciter actually plays in, given the preferred one. */
export function effectiveMode(r: Reciter, preferred: "surah" | "ayah"): "surah" | "ayah" {
  if (preferred === "surah" && r.qdc) return "surah";
  return r.ayah ? "ayah" : "surah";
}

export function reciter(id: string): Reciter {
  return RECITERS.filter((r) => r.id === id)[0] || RECITERS[0];
}

export interface Translation { id: string; name: string; language: string }
export const TRANSLATIONS: Translation[] = [
  { id: "en.sahih", name: "Saheeh International", language: "English" },
  { id: "en.pickthall", name: "Pickthall", language: "English" },
  { id: "en.yusufali", name: "Yusuf Ali", language: "English" },
  { id: "en.asad", name: "Muhammad Asad", language: "English" },
  { id: "fr.hamidullah", name: "Hamidullah", language: "French" },
  { id: "ur.jalandhry", name: "Jalandhry", language: "Urdu" },
  { id: "id.indonesian", name: "Bahasa Indonesia", language: "Indonesian" },
  { id: "tr.diyanet", name: "Diyanet İşleri", language: "Turkish" },
];

export function translation(id: string): Translation {
  return TRANSLATIONS.filter((t) => t.id === id)[0] || TRANSLATIONS[0];
}
